-- Trong books.sample.json: price = giá gốc, sale_price = giá bán khi giảm giá.

BEGIN;

INSERT INTO categories (name, slug, description, sort_order) VALUES
  ('Văn học', 'van-hoc', 'Tiểu thuyết, truyện ngắn và tản văn cho cả nhà.', 1),
  ('Kinh tế', 'kinh-te', 'Quản lý tiền bạc và tài chính gia đình.', 2),
  ('Kỹ năng', 'ky-nang', 'Kỹ năng làm cha mẹ và đồng hành cùng con.', 3),
  ('Thiếu nhi', 'thieu-nhi', 'Truyện tranh và sách khám phá cho bé.', 4)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO books
  (id, category_id, title, slug, author, publisher, publish_year, pages, description,
   age_min, age_max, price, original_price, stock, cover_url, is_featured, is_active)
VALUES
  ('5f1c0a01-3b7e-4d21-9a10-000000000001',
   (SELECT id FROM categories WHERE slug = 'van-hoc'),
   'Con Đường Mưa Tháng Bảy', 'con-duong-mua-thang-bay', 'Lâm Thanh Hòa', 'NXB Hoa Sim', 2024, 312,
   'Sau mười năm rời quê, Hạnh trở về ngôi nhà ven sông để lo hậu sự cho người bà đã nuôi mình khôn lớn. Trong những ngày mưa kéo dài suốt tháng bảy, chị lần giở từng chiếc rương cũ, gặp lại bạn xưa và dần hiểu những im lặng của gia đình. Bằng giọng văn chậm rãi, giàu hình ảnh, tác giả kể về sự tha thứ, nỗi nhớ và việc ta cần quay lại một nơi để biết mình đã lớn lên thế nào. Cuốn tiểu thuyết dịu dàng cho những buổi tối yên tĩnh.',
   NULL, NULL, 109000, 128000, 35, 'assets/covers/con-duong-mua-thang-bay.svg', true, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000002',
   (SELECT id FROM categories WHERE slug = 'van-hoc'),
   'Những Ngọn Đèn Ở Cuối Phố', 'nhung-ngon-den-o-cuoi-pho', 'Đào Minh Khuê', 'NXB Lá Bàng', 2023, 224,
   'Tập truyện ngắn gồm mười hai câu chuyện nhỏ về tuổi mười lăm: một đứa trẻ giấu điểm kém, một cô bé học cách chia tay người bạn thân, một cậu bé bán vé số mơ về chuyến tàu đêm. Mỗi truyện sáng lên như một ngọn đèn ở cuối con phố quen. Lời văn trong trẻo, nhiều chi tiết gần gũi, phù hợp để thiếu niên tự đọc và để cha mẹ đọc cùng, rồi ngồi lại trò chuyện với con.',
   12, 18, 98000, NULL, 42, 'assets/covers/nhung-ngon-den-o-cuoi-pho.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000003',
   (SELECT id FROM categories WHERE slug = 'kinh-te'),
   'Tiền Nhà Mình, Bài Toán Nhà Mình', 'tien-nha-minh-bai-toan-nha-minh', 'Phan Gia Bảo', 'NXB Cây Cau', 2025, 288,
   'Cuốn sách hướng dẫn quản lý tài chính gia đình bằng ngôn ngữ đời thường, không thuật ngữ rối rắm. Tác giả chia thu nhập thành bốn khoản dễ nhớ, chỉ cách lập quỹ khẩn cấp, lên kế hoạch học phí cho con và tránh những khoản nợ nhỏ nhưng dai dẳng. Mỗi chương đều có bảng tính mẫu và bài tập ngắn để cả nhà cùng làm vào cuối tuần. Dành cho cha mẹ muốn tiền bạc bớt là nỗi lo và thành một câu chuyện chung của gia đình.',
   NULL, NULL, 142000, 169000, 28, 'assets/covers/tien-nha-minh-bai-toan-nha-minh.svg', true, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000004',
   (SELECT id FROM categories WHERE slug = 'kinh-te'),
   'Ngân Sách Nhỏ, Ước Mơ Lớn', 'ngan-sach-nho-uoc-mo-lon', 'Trịnh Hoài Thương', 'NXB Gió Đồng', 2023, 256,
   'Làm thế nào để vừa chi tiêu hợp lý vừa dành được một khoản cho ước mơ? Tác giả kể lại hành trình mười năm của một gia đình thu nhập trung bình, từ những tháng cuối tháng hụt tiền đến ngày mua được căn nhà nhỏ. Sách giới thiệu phương pháp phong bì, quy tắc hai mươi bốn giờ trước khi mua sắm và cách dạy trẻ dùng tiền tiết kiệm. Văn phong gần gũi, nhiều ví dụ thực tế, dễ áp dụng ngay từ tháng này.',
   NULL, NULL, 149000, NULL, 20, 'assets/covers/ngan-sach-nho-uoc-mo-lon.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000005',
   (SELECT id FROM categories WHERE slug = 'ky-nang'),
   'Mười Phút Lắng Nghe Con', 'muoi-phut-lang-nghe-con', 'Võ Thanh Mai', 'NXB Vầng Trăng', 2024, 200,
   'Chỉ mười phút mỗi ngày, không điện thoại, không phán xét, cha mẹ có thể thay đổi cách con mở lòng. Cuốn sách trình bày ba bước lắng nghe đơn giản, kèm những câu hỏi gợi mở phù hợp từng độ tuổi và các tình huống hay gặp như con im lặng, con cãi lại hay con nói dối. Tác giả là giáo viên tiểu học lâu năm, chia sẻ bằng nhiều câu chuyện thật và bài tập nhỏ để bố mẹ thực hành ngay tối nay.',
   NULL, NULL, 95000, 119000, 50, 'assets/covers/muoi-phut-lang-nghe-con.svg', true, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000006',
   (SELECT id FROM categories WHERE slug = 'ky-nang'),
   'Bình Tĩnh Khi Con Nổi Giận', 'binh-tinh-khi-con-noi-gian', 'Ngô Khánh An', 'NXB Vầng Trăng', 2025, 240,
   'Con khóc lóc giữa siêu thị, la hét khi bị tắt tivi, hay đóng sầm cửa phòng. Cha mẹ nên làm gì để vừa giữ bình tĩnh vừa dạy con quản lý cảm xúc? Cuốn sách giải thích vì sao trẻ bùng nổ, đưa ra năm kỹ thuật hạ nhiệt cho cả người lớn lẫn trẻ nhỏ và nhiều mẫu câu nên nói trong lúc căng thẳng. Có phần dành riêng cho trẻ từ ba đến mười một tuổi, dễ đọc, dễ nhớ và dễ làm theo.',
   NULL, NULL, 135000, NULL, 38, 'assets/covers/binh-tinh-khi-con-noi-gian.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000007',
   (SELECT id FROM categories WHERE slug = 'thieu-nhi'),
   'Chú Sóc Nhỏ Tìm Mùa Thu', 'chu-soc-nho-tim-mua-thu', 'Hạ Vy', 'NXB Hạt Dẻ', 2024, 32,
   'Chú sóc Nâu thức dậy và thấy khu rừng vẫn xanh um, không thấy mùa thu đâu cả. Chú lên đường hỏi chim sẻ, hỏi gió, hỏi cả chiếc lá vàng cuối cùng để tìm xem mùa thu đang trốn ở đâu. Truyện tranh với những trang màu ấm áp, câu chữ ngắn, nhịp điệu lặp lại giúp bé dễ nhớ và thích đọc to cùng bố mẹ. Cuối sách có trò chơi tìm hạt dẻ để bé luyện quan sát.',
   3, 6, 49000, 59000, 60, 'assets/covers/chu-soc-nho-tim-mua-thu.svg', true, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000008',
   (SELECT id FROM categories WHERE slug = 'thieu-nhi'),
   'Mầm Đậu Biết Nói', 'mam-dau-biet-noi', 'Bùi Thảo Nguyên', 'NXB Hạt Dẻ', 2023, 28,
   'Trong chiếc cốc nhỏ trên bệ cửa sổ, một mầm đậu bắt đầu kể chuyện mỗi sáng. Mầm đậu kể về giọt nước, về ánh nắng và về niềm vui khi được lớn lên từng chút một. Sách giúp trẻ làm quen với vòng đời của cây qua lời kể ngộ nghĩnh và tranh minh họa tươi sáng. Phần cuối hướng dẫn bé tự gieo hạt tại nhà với bố mẹ, ghi lại nhật ký cây trong bảy ngày liền.',
   4, 7, 52000, NULL, 45, 'assets/covers/mam-dau-biet-noi.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000009',
   (SELECT id FROM categories WHERE slug = 'thieu-nhi'),
   'Nhà Máy Cầu Vồng Của Bi', 'nha-may-cau-vong-cua-bi', 'Lý Tuấn Kiệt', 'NXB Gió Đồng', 2025, 96,
   'Bi là cậu bé tò mò, luôn hỏi vì sao trời mưa rồi mới có cầu vồng. Một đêm nọ, Bi lạc vào nhà máy cầu vồng bí mật, nơi những chú thợ mây pha màu từ ánh nắng và hơi nước. Qua cuộc phiêu lưu vui nhộn, các bạn nhỏ khám phá kiến thức đơn giản về ánh sáng và thời tiết. Mỗi chương ngắn kèm một thí nghiệm an toàn có thể làm ở nhà cùng bố mẹ.',
   6, 9, 76000, 89000, 30, 'assets/covers/nha-may-cau-vong-cua-bi.svg', true, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000010',
   (SELECT id FROM categories WHERE slug = 'thieu-nhi'),
   'Bí Mật Của Chiếc Cặp Xanh', 'bi-mat-cua-chiec-cap-xanh', 'Đoàn Minh Thư', 'NXB Gió Đồng', 2022, 144,
   'Lớp ba B bỗng xuất hiện một chiếc cặp màu xanh không ai nhận, và mỗi ngày bên trong lại có một món đồ lạ. Nhóm bạn nhỏ cùng nhau lần theo từng manh mối để tìm chủ nhân, và trên đường đi họ học được cách chia sẻ, trung thực và lắng nghe nhau. Truyện trinh thám nhẹ nhàng, nhiều tình huống hài hước, chữ lớn dễ đọc, phù hợp để các em bắt đầu tự đọc một cuốn sách dài đầu tiên.',
   8, 11, 95000, NULL, 25, 'assets/covers/bi-mat-cua-chiec-cap-xanh.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000011',
   (SELECT id FROM categories WHERE slug = 'van-hoc'),
   'Thư Gửi Mùa Nắng Muộn', 'thu-gui-mua-nang-muon', 'Hoàng Ngọc Trâm', 'NXB Lá Bàng', 2024, 192,
   'Tập tản văn gồm ba mươi lá thư không bao giờ gửi đi: thư cho người mẹ bận rộn, cho cô bạn cũ ở xóm trọ, cho chính mình năm hai mươi tuổi. Tác giả viết về những điều nhỏ bé như mùi cơm mới, tiếng xe bán bánh mì buổi sớm, cơn mưa bất chợt giữa chiều. Giọng văn nhẹ, đôi chỗ hóm hỉnh, đọc mỗi tối một thư là vừa. Cuốn sách hợp để tặng cha mẹ, bạn bè hoặc tự thưởng cho mình sau một tuần dài.',
   NULL, NULL, 89000, 105000, 33, 'assets/covers/thu-gui-mua-nang-muon.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000012',
   (SELECT id FROM categories WHERE slug = 'van-hoc'),
   'Cánh Đồng Có Tiếng Sáo', 'canh-dong-co-tieng-sao', 'Tạ Bình Nguyên', 'NXB Hoa Sim', 2022, 280,
   'Mùa hè năm mười ba tuổi, Tín bị gửi về quê ngoại và quen một cậu bé chăn trâu thổi sáo rất hay. Từ những buổi chiều thả diều, những đêm bắt đom đóm, hai đứa trẻ khác biệt dần trở thành bạn thân. Tiểu thuyết dành cho tuổi mới lớn, nói về tình bạn, sự trưởng thành và cả những lần hiểu lầm cha mẹ. Ngôn ngữ giản dị, nhiều hình ảnh đồng quê, phù hợp để thiếu niên đọc một mạch.',
   12, 18, 115000, NULL, 27, 'assets/covers/canh-dong-co-tieng-sao.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000013',
   (SELECT id FROM categories WHERE slug = 'kinh-te'),
   'Cửa Hàng Nhỏ, Sổ Sách Rõ', 'cua-hang-nho-so-sach-ro', 'Dương Kim Ngân', 'NXB Cây Cau', 2024, 272,
   'Dành cho những gia đình đang buôn bán nhỏ tại nhà, cuốn sách hướng dẫn ghi chép thu chi từ đơn giản nhất bằng một cuốn sổ hoặc một bảng tính. Tác giả giải thích cách tách tiền cửa hàng khỏi tiền sinh hoạt, tính giá vốn, theo dõi hàng tồn và biết khi nào nên mở rộng. Mỗi chương có biểu mẫu in sẵn và ví dụ từ quán cà phê, tiệm tạp hóa, cửa hàng quần áo. Ngôn ngữ dễ hiểu, không đòi hỏi kiến thức kế toán.',
   NULL, NULL, 129000, 159000, 22, 'assets/covers/cua-hang-nho-so-sach-ro.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000014',
   (SELECT id FROM categories WHERE slug = 'kinh-te'),
   'Dạy Con Giữ Tiền Từ Chiếc Heo Đất', 'day-con-giu-tien-tu-chiec-heo-dat', 'Hồ Quỳnh Chi', 'NXB Gió Đồng', 2025, 208,
   'Trẻ nên biết về tiền từ khi nào và dạy bằng cách nào để không biến con thành người tính toán quá sớm? Cuốn sách đưa ra lộ trình theo ba giai đoạn tuổi: nhận biết giá trị đồng tiền, tập tiết kiệm và tập chi tiêu có kế hoạch. Mỗi giai đoạn có trò chơi, câu chuyện nhỏ và những câu hỏi gợi mở cho bố mẹ. Tác giả nhấn mạnh việc làm gương, để con học cách trân trọng tiền bạc từ chính nếp sống trong nhà.',
   NULL, NULL, 125000, NULL, 40, 'assets/covers/day-con-giu-tien-tu-chiec-heo-dat.svg', true, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000015',
   (SELECT id FROM categories WHERE slug = 'ky-nang'),
   'Nếp Nhà Buổi Tối', 'nep-nha-buoi-toi', 'Mai Bích Ngọc', 'NXB Vầng Trăng', 2024, 224,
   'Buổi tối thường là lúc cả nhà mệt nhất, và cũng dễ cáu nhất. Cuốn sách gợi ý ba mươi thói quen nhỏ để buổi tối nhẹ nhàng hơn: bữa cơm không điện thoại, mười lăm phút dọn nhà chung, một câu chuyện trước khi ngủ. Mỗi thói quen chỉ gói gọn trong hai trang, có phần thử một tuần và ghi chép cảm nhận. Bố mẹ không cần làm tất cả, chỉ cần chọn vài điều hợp với nhà mình và kiên nhẫn duy trì.',
   NULL, NULL, 109000, 129000, 3, 'assets/covers/nep-nha-buoi-toi.svg', false, true),
  ('5f1c0a01-3b7e-4d21-9a10-000000000016',
   (SELECT id FROM categories WHERE slug = 'ky-nang'),
   'Nói Không Mà Con Vẫn Thương Mẹ', 'noi-khong-ma-con-van-thuong-me', 'Cao Hải Yến', 'NXB Vầng Trăng', 2023, 232,
   'Nhiều bố mẹ ngại từ chối con vì sợ con buồn, nhưng cứ chiều mãi lại thành áp lực. Cuốn sách chỉ ra cách nói không một cách rõ ràng, ấm áp và nhất quán, kèm những mẫu câu cho từng tình huống: con đòi đồ chơi, xin xem thêm hoạt hình, hay không chịu đi ngủ. Tác giả cũng hướng dẫn cách đặt ranh giới mà không to tiếng, và cách giữ sự gần gũi sau mỗi lần từ chối. Dễ đọc, nhiều ví dụ thực tế từ chính các gia đình.',
   NULL, NULL, 139000, NULL, 0, 'assets/covers/noi-khong-ma-con-van-thuong-me.svg', false, true)
ON CONFLICT (slug) DO NOTHING;

COMMIT;
